PRAGMA foreign_keys=OFF;
DROP TABLE IF EXISTS audit_events; DROP TABLE IF EXISTS reviews; DROP TABLE IF EXISTS booking_messages; DROP TABLE IF EXISTS cancellations; DROP TABLE IF EXISTS invoices; DROP TABLE IF EXISTS payments; DROP TABLE IF EXISTS stays; DROP TABLE IF EXISTS bookings; DROP TABLE IF EXISTS booking_quotes; DROP TABLE IF EXISTS rooms; DROP TABLE IF EXISTS rate_plans; DROP TABLE IF EXISTS cancellation_policies; DROP TABLE IF EXISTS room_types; DROP TABLE IF EXISTS reset_tokens; DROP TABLE IF EXISTS sessions; DROP TABLE IF EXISTS users;
PRAGMA foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE reset_tokens(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,expires_at TEXT NOT NULL,used_at TEXT);
CREATE TABLE room_types(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,description TEXT NOT NULL,capacity_adults INTEGER NOT NULL,capacity_children INTEGER NOT NULL,amenities TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE cancellation_policies(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,free_hours INTEGER NOT NULL,fee_percent INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE rate_plans(id INTEGER PRIMARY KEY,room_type_id INTEGER NOT NULL REFERENCES room_types(id),policy_id INTEGER NOT NULL REFERENCES cancellation_policies(id),name TEXT NOT NULL,nightly_rate_cents INTEGER NOT NULL,valid_from TEXT NOT NULL,valid_to TEXT NOT NULL,max_adults INTEGER NOT NULL,max_children INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,UNIQUE(room_type_id,name,valid_from,valid_to));
CREATE TABLE rooms(id INTEGER PRIMARY KEY,number TEXT UNIQUE NOT NULL,room_type_id INTEGER NOT NULL REFERENCES room_types(id),status TEXT NOT NULL DEFAULT 'available',maintenance_reason TEXT,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE booking_quotes(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),room_type_id INTEGER NOT NULL REFERENCES room_types(id),rate_plan_id INTEGER NOT NULL REFERENCES rate_plans(id),policy_id INTEGER NOT NULL REFERENCES cancellation_policies(id),check_in TEXT NOT NULL,check_out TEXT NOT NULL,adults INTEGER NOT NULL,children INTEGER NOT NULL,nightly_rate_cents INTEGER NOT NULL,total_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE bookings(id INTEGER PRIMARY KEY,confirmation_code TEXT UNIQUE NOT NULL,guest_id INTEGER NOT NULL REFERENCES users(id),created_by INTEGER NOT NULL REFERENCES users(id),room_type_id INTEGER NOT NULL REFERENCES room_types(id),room_id INTEGER REFERENCES rooms(id),check_in TEXT NOT NULL,check_out TEXT NOT NULL,adults INTEGER NOT NULL,children INTEGER NOT NULL,total_cents INTEGER NOT NULL,policy_name TEXT NOT NULL,free_hours INTEGER NOT NULL,fee_percent INTEGER NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL);
CREATE TABLE stays(id INTEGER PRIMARY KEY,booking_id INTEGER UNIQUE NOT NULL REFERENCES bookings(id),room_id INTEGER NOT NULL REFERENCES rooms(id),checked_in_at TEXT NOT NULL,checked_out_at TEXT,incidentals_cents INTEGER NOT NULL DEFAULT 0);
CREATE TABLE payments(id INTEGER PRIMARY KEY,booking_id INTEGER NOT NULL REFERENCES bookings(id),amount_cents INTEGER NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,method_ref TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE invoices(id INTEGER PRIMARY KEY,booking_id INTEGER UNIQUE NOT NULL REFERENCES bookings(id),room_cents INTEGER NOT NULL,incidentals_cents INTEGER NOT NULL DEFAULT 0,refund_cents INTEGER NOT NULL DEFAULT 0,total_cents INTEGER NOT NULL,status TEXT NOT NULL,finalized_at TEXT);
CREATE TABLE cancellations(id INTEGER PRIMARY KEY,booking_id INTEGER UNIQUE NOT NULL REFERENCES bookings(id),reason TEXT NOT NULL,fee_cents INTEGER NOT NULL,refund_cents INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE booking_messages(id INTEGER PRIMARY KEY,booking_id INTEGER NOT NULL REFERENCES bookings(id),sender_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL);
CREATE TABLE reviews(id INTEGER PRIMARY KEY,booking_id INTEGER UNIQUE NOT NULL REFERENCES bookings(id),room_type_id INTEGER NOT NULL REFERENCES room_types(id),author_id INTEGER NOT NULL REFERENCES users(id),rating INTEGER NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,moderation_status TEXT NOT NULL DEFAULT 'published',moderation_reason TEXT,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE audit_events(id INTEGER PRIMARY KEY,actor_id INTEGER NOT NULL REFERENCES users(id),action TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
